  "ss.encrypted": { zh: "已加密：{name}（7-Zip 输此密码可恢复；忘记密码内容永久找不回）", en: "Encrypted: {name} (recoverable with this password in 7-Zip; if you forget it the content is lost forever)", ja: "暗号化しました：{name}（7-Zip でこのパスワードを入力すれば復元可能。パスワードを忘れると内容は永久に取り戻せません）", tok: "len li lon: {name}. ilo \"7-Zip\" en nimi len ni li ken open e ona. sina weka e nimi len la sitelen li moli. sina ken ala open e ona lon tenpo ale." }, 
  "ss.encryptFailed": { zh: "加密失败：{error}", en: "Encryption failed: {error}", ja: "暗号化に失敗しました：{error}", tok: "len li pakala: {error}" }, 
  "ss.noDocOpen": { zh: "没打开作品", en: "No artwork open", ja: "作品が開かれていません", tok: "sitelen li open ala" }, 
  "ss.notEncrypted": { zh: "这不是加密作品", en: "This is not an encrypted artwork", ja: "これは暗号化された作品ではありません", tok: "sitelen ni li jo e len ala" }, 
  "ss.decryptConfirmTitle": { zh: "解除当前作品的加密？", en: "Remove encryption from the current artwork?", ja: "現在の作品の暗号化を解除しますか？", tok: "sina wile ala wile weka e len tan sitelen ni?" }, 
  "ss.decryptConfirmMsg": { zh: "内容将以明文存放在本机与云端，任何能访问此设备或云账号的人都能查看。", en: "The content will be stored in plain text locally and in the cloud; anyone with access to this device or cloud account can view it.", ja: "内容はローカルとクラウドに平文で保存され、このデバイスやクラウドアカウントにアクセスできる人は誰でも閲覧できます。", tok: "len li weka la sitelen li open tawa jan ale. ona li lon ilo ni li lon poki sewi. jan pi ken open li ken lukin e ona." }, 
  "ss.cancelledNeedPassword": { zh: "已取消（需要密码）", en: "Cancelled (password required)", ja: "キャンセルしました（パスワードが必要です）", tok: "pali li weka (nimi len li wile)" }, 
  "ss.decryptingBusy": { zh: "正在解除加密 {name}…", en: "Removing encryption from {name}…", ja: "{name} の暗号化を解除しています…", tok: "mi weka e len tan {name}…" }, 
  "ss.decryptNeedsOnline": { zh: "已同步过云端的作品需在线解除加密", en: "Artworks already synced to the cloud must be decrypted online", ja: "クラウドに同期済みの作品はオンラインで暗号化を解除する必要があります", tok: "sitelen li lon poki sewi kin. ilo li wile ken toki tawa poki sewi." }, 
  "ss.decrypted": { zh: "已解除加密：{name}", en: "Encryption removed: {name}", ja: "暗号化を解除しました：{name}", tok: "len li weka: {name}" }, 
  "ss.decryptFailed": { zh: "解除加密失败：{error}", en: "Failed to remove encryption: {error}", ja: "暗号化の解除に失敗しました：{error}", tok: "weka len li pakala: {error}" }, 
  "ss.renameTitleWith": { zh: "重命名（{detail}）", en: "Rename ({detail})", ja: "名前を変更（{detail}）", tok: "ante nimi ({detail})" }, 
  "ss.renameTitle": { zh: "重命名当前画作", en: "Rename current artwork", ja: "現在の作品の名前を変更", tok: "ante nimi pi sitelen ni" }, 
  "ss.artworkNamePlaceholder": { zh: "作品名字", en: "Artwork name", ja: "作品名", tok: "nimi sitelen" }, 
  "ss.nameCannotBeEmpty": { zh: "名字不能空", en: "Name can't be empty", ja: "名前は空にできません", tok: "nimi li wile lon" }, 
  "ss.renamingBusy": { zh: "正在重命名 {oldName} → {newName}…", en: "Renaming {oldName} → {newName}…", ja: "{oldName} → {newName} に名前を変更しています…", tok: "mi ante e nimi: {oldName} → {newName}…" }, 
  "ss.renamedWithCloud": { zh: "已重命名（含云端）：{oldName} → {newName}", en: "Renamed (including cloud): {oldName} → {newName}", ja: "名前を変更しました（クラウドを含む）：{oldName} → {newName}", tok: "nimi li ante (lon poki sewi kin): {oldName} → {newName}" }, // 改名的旧名去向三态（v432）：谱系不明时改名降级为「另存」，旧名留在云端 —— 必须说清楚，
  //   否则用户以为旧的没了（而上一版是真把它挪进回收站了）。
  "ss.renamedOldKept": { zh: "已另存为「{newName}」。云端的「{oldName}」原样留着（本地这份的来历不明，没敢动它）", en: "Saved as \"{newName}\". The cloud copy \"{oldName}\" was left untouched (this local copy's lineage is unknown).", ja: "「{newName}」として保存しました。クラウドの「{oldName}」はそのまま残しています（このローカル版の由来が不明なため）", tok: "mi awen e ona kepeken nimi sin \"{newName}\". sitelen \"{oldName}\" pi poki sewi li awen sama. mi sona pona ala e tan ona la mi ante ala e ona." }, 
  "ss.renamedOldUnknown": { zh: "已另存为「{newName}」。云端的「{oldName}」没能查到状态（离线？），所以没有动它——请稍后自行确认", en: "Saved as \"{newName}\". Couldn't reach the cloud to check \"{oldName}\", so it was left alone — please verify later.", ja: "「{newName}」として保存しました。クラウドの「{oldName}」の状態を確認できなかったため（オフライン？）、触れていません。後でご確認ください", tok: "mi awen e ona kepeken nimi sin \"{newName}\". mi ken ala lukin e \"{oldName}\" lon poki sewi. mi ante ala e ona. o lukin lon tenpo kama." }, 
  "ss.renamedLocalOnly": { zh: "已重命名为「{newName}」，但云端没推成功——目前只在本地，稍后会重试", en: "Renamed to \"{newName}\", but the cloud push failed — it's local-only for now and will retry later.", ja: "「{newName}」に名前を変更しましたが、クラウドへの送信に失敗しました。現在はローカルのみで、後で再試行します", tok: "nimi sin li lon: \"{newName}\". taso pana tawa poki sewi li pakala. ona li lon ilo ni taso. mi pali sin lon tenpo kama." }, 
  "ss.renamedOldOrphan": { zh: "已重命名为「{newName}」，但云端的「{oldName}」没能移进回收站，仍留在原处", en: "Renamed to \"{newName}\", but the cloud copy \"{oldName}\" couldn't be moved to the recycle bin and remains in place.", ja: "「{newName}」に名前を変更しましたが、クラウドの「{oldName}」をごみ箱に移動できず、元の場所に残っています", tok: "nimi sin li lon: \"{newName}\". taso \"{oldName}\" pi poki sewi li ken ala tawa poki jaki. ona li awen lon ma ona." }, 
  "ss.renameFailed": { zh: "重命名失败：{error}", en: "Rename failed: {error}", ja: "名前の変更に失敗しました：{error}", tok: "ante nimi li pakala: {error}" }, 
  "ss.localNameTakenStatus": { zh: "本地已有同名 \"{name}\"，换一个", en: "\"{name}\" already exists locally; choose another", ja: "ローカルに同名の「{name}」がすでにあります。別の名前にしてください", tok: "nimi sama \"{name}\" li lon ilo ni. o ante." }, 
  "ss.nameTakenNote": { zh: "已有同名 \"{name}\"，换一个", en: "\"{name}\" already exists; choose another", ja: "同名の「{name}」がすでにあります。別の名前にしてください", tok: "nimi sama \"{name}\" li lon. o ante." }, 
  "ss.savingBusy": { zh: "正在保存 {name}…", en: "Saving {name}…", ja: "{name} を保存しています…", tok: "mi awen e {name}…" }, 
  "ss.localSaveIncompleteTitle": { zh: "本地保存未完成", en: "Local save incomplete", ja: "ローカル保存が完了していません", tok: "awen li pini ala" }, 
