  "tm.cloudNameExists": { zh: "云端已有同名 \"{name}\"，换一个", en: "A cloud file named \"{name}\" already exists, choose another", ja: "クラウドに同名 \"{name}\" が既にあります。別の名前にしてください", tok: "nimi \"{name}\" li lon poki sewi. o pana e nimi ante." },
  "tm.nameExists":      { zh: "已有同名 \"{name}\"（本地或云端），换一个", en: "A file named \"{name}\" already exists (local or cloud), choose another", ja: "同名 \"{name}\" が既にあります（ローカルまたはクラウド）。別の名前にしてください", tok: "nimi \"{name}\" li lon (ilo ni anu poki sewi). o pana e nimi ante." },
  "tm.savedAsWithCloud": { zh: "已另存为（含云端）：{name}", en: "Saved as (incl. cloud): {name}", ja: "名前を付けて保存しました（クラウド含む）：{name}", tok: "mi awen e ona kepeken nimi sin (lon poki sewi kin): {name}" },
  "tm.saveAsFailed": { zh: "另存为失败：{err}", en: "Save As failed: {err}", ja: "名前を付けて保存に失敗しました：{err}", tok: "awen li pakala: {err}" },
