  "tm.revertTitle": { zh: "撤销修改", en: "Revert changes", ja: "変更を元に戻す", tok: "kama sin tawa tenpo pini" },
  "tm.revertMessage": { zh: "回到约 {min} 分钟前的快照（本次打开或上次保存时的版本）。\n之后所有修改将丢失。", en: "Revert to the snapshot from about {min} minutes ago (when opened or last saved). All changes after that will be lost.", ja: "約 {min} 分前のスナップショット（開いた時または最後に保存した時の状態）に戻ります。\nそれ以降の変更はすべて失われます。", tok: "sitelen li kama sama tenpo pini ({min} tenpo lili). ante ale pi tenpo ni li weka. sina ken ala weka e pali ni." },
  "tm.cancel": { zh: "取消", en: "Cancel", ja: "キャンセル", tok: "weka" },
