  "tm.revertFailedNeedPassword": { zh: "恢复失败：需要密码解锁", en: "Restore failed: password required to unlock", ja: "復元に失敗しました：ロック解除にパスワードが必要です", tok: "kama sin li pakala: nimi len li wile" },
  "tm.revertedToOpen": { zh: "已恢复到本次打开时（{min} 分钟前）", en: "Restored to when opened ({min} minutes ago)", ja: "開いた時点に復元しました（{min} 分前）", tok: "mi kama sin e sitelen pi tenpo open ({min} tenpo lili pini)" },
  "tm.revertFailed": { zh: "恢复失败：{err}", en: "Restore failed: {err}", ja: "復元に失敗しました：{err}", tok: "kama sin li pakala: {err}" },
  "tm.viewportReset": { zh: "视口已复位", en: "Viewport reset", ja: "ビューをリセットしました", tok: "lukin li kama sin" },
  "tm.forceResetTitle": { zh: "强制清缓存重启？", en: "Force-clear cache and restart?", ja: "キャッシュを強制的にクリアして再起動しますか？", tok: "o weka e poki tenpo o open sin" },
  "tm.forceResetBody": { zh: "会清掉 SW + Cache Storage，强制重新拉所有 JS / CSS。你的画 / 笔架（IDB / OneDrive）不会动。\n用途：PWA 卡老版本，点更新还是老的时候用。", en: "Clears the SW + Cache Storage and force-refetches all JS / CSS. Your artwork / brush rack (IDB / OneDrive) is untouched.\nUse when the PWA is stuck on an old version and Update doesn't help.", ja: "SW と Cache Storage を消去し、すべての JS / CSS を強制的に再取得します。作品 / ブラシラック（IDB / OneDrive）はそのままです。\n用途：PWA が古いバージョンで固まり、更新を押しても変わらない時に使います。", tok: "mi weka e poki tenpo. mi kama jo sin e ijo ale mi. sitelen sina en poki pi ilo sitelen li awen pona. mi awen lon nanpa pini la o kepeken e ni." },
  "tm.cacheClearedReloading": { zh: "已清缓存，正在硬重载…", en: "Cache cleared, hard-reloading…", ja: "キャッシュを消去しました。強制再読み込み中…", tok: "poki tenpo li weka. mi open sin…" },
  "tm.cacheClearFailed": { zh: "清缓存失败：{err}", en: "Failed to clear cache: {err}", ja: "キャッシュの消去に失敗しました：{err}", tok: "weka li pakala: {err}" },
  "tm.resetRackTitle": { zh: "还原内置笔刷？", en: "Restore built-in brushes?", ja: "内蔵ブラシを復元しますか？", tok: "sina wile ala wile kama sin e ilo pi tan open?" },
  "tm.resetRackBody": { zh: "把内置笔刷恢复成出厂设置，并排到各分组最前。你自己新建或导入的笔刷不会被删除；只有内置笔上的改动会被覆盖。", en: "Restores the built-in brushes to their factory settings and moves them to the top of each folder. Your own brushes are not deleted \u2014 only edits made to built-in brushes are overwritten.", ja: "内蔵ブラシを工場出荷時の設定に戻し、各フォルダーの先頭に並べ替えます。自作・読み込んだブラシは削除されません。内蔵ブラシへの変更のみ上書きされます。", tok: "ilo pi tan open li kama sama open. ona li tawa sewi poki. ilo pi pali sina li weka ala. taso, sina ante e ilo pi tan open la ante ni li weka." },
  "tm.rackRestored": { zh: "已还原 {count} 支内置笔刷", en: "Restored {count} built-in brushes", ja: "内蔵ブラシ {count} 本を復元しました", tok: "mi kama sin e ilo pi tan open ({count})" },
  "tm.rotationResetForCrop": { zh: "已复位画布旋转以进入自由裁切", en: "Canvas rotation reset to enter free crop", ja: "自由トリミングに入るためキャンバスの回転をリセットしました", tok: "sike supa li kama sin. kipisi li open." },
  "tm.noSelectionDrawLasso": { zh: "没选区——画一个 lasso 选区先", en: "No selection — draw a lasso selection first", ja: "選択範囲がありません——先に投げ縄で選択してください", tok: "ma wile li lon ala. o sitelen e ma wile kepeken ilo pi ma wile." },
  "tm.selectionTooSmall": { zh: "选区太小或在画布外", en: "Selection too small or outside the canvas", ja: "選択範囲が小さすぎるか、キャンバスの外です", tok: "ma wile li lili ike. ken la ona li lon ala supa." },
  "tm.croppedToSelection": { zh: "已裁到选区：{w}×{h}", en: "Cropped to selection: {w}×{h}", ja: "選択範囲でトリミングしました：{w}×{h}", tok: "mi kipisi tawa ma wile: {w}×{h}" },
  "tm.flippedHorizontal": { zh: "已水平翻转", en: "Flipped horizontally", ja: "左右反転しました", tok: "mi jasima e poka sitelen" },
