  "tm.cropped": { zh: "已裁切：{w}×{h}", en: "Cropped: {w}×{h}", ja: "トリミングしました：{w}×{h}", tok: "mi kipisi: {w}×{h}" },
  "tm.sizeOutOfRange": { zh: "尺寸超出 [1, 8192]", en: "Size out of range [1, 8192]", ja: "サイズが範囲外です [1, 8192]", tok: "suli li lon ala poki nanpa [1, 8192]" },
  "tm.resampled": { zh: "已重采样到 {w}×{h}（{mode}）", en: "Resampled to {w}×{h} ({mode})", ja: "{w}×{h} にリサンプリングしました（{mode}）", tok: "mi ante e suli: {w}×{h} ({mode})" },
  "tm.offset": { zh: "已偏移 {dx},{dy}（环绕）", en: "Offset {dx},{dy} (wrap)", ja: "{dx},{dy} オフセットしました（ラップ）", tok: "mi tawa sike e sitelen: {dx},{dy}" },
  "tm.dotExtDownloaded": { zh: ".{ext} 已下载", en: ".{ext} downloaded", ja: ".{ext} をダウンロードしました", tok: "lipu .{ext} li kama lon ilo sina" },
